CREATE OR REPLACE FUNCTION public.anonymize_contact(p_contact_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_owner_id uuid;
  v_sales_preserved integer := 0;
  v_tasks_deleted integer := 0;
  v_tasks_scrubbed integer := 0;
  v_partners_unlinked integer := 0;
  v_templates_archived integer := 0;
begin
  if v_user_id is null then
    raise exception using errcode = '42501', message = 'authentication_required';
  end if;
  if not public.has_app_entitlement(v_user_id) then
    raise exception using errcode = '42501', message = 'app_entitlement_required';
  end if;
  if p_contact_id is null then
    raise exception using errcode = '22023', message = 'contact_id_required';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('zynergia_partner_graph', 0)
  );

  select user_id
    into v_owner_id
    from public.contacts
   where id = p_contact_id
   for update;

  -- Repeating a completed deletion is a harmless no-op. An existing contact
  -- owned by someone else is rejected explicitly below.
  if not found then
    return jsonb_build_object(
      'status', 'already_removed',
      'contact_id', p_contact_id
    );
  end if;
  if v_owner_id <> v_user_id then
    raise exception using errcode = '42501', message = 'contact_not_owned';
  end if;

  -- Keep aggregate sales history but remove the personal link.
  update public.sales
     set contact_id = null
   where user_id = v_user_id
     and contact_id = p_contact_id;
  get diagnostics v_sales_preserved = row_count;

  -- Every unfinished task is future work, even when its due date has passed.
  delete from public.tasks
   where user_id = v_user_id
     and contact_id = p_contact_id
     and not coalesce(completed, false);
  get diagnostics v_tasks_deleted = row_count;

  -- Preserve completed task counts without retaining the contact identifier or
  -- a free-text task name that may contain the person's name.
  update public.tasks
     set contact_id = null,
         task_name = case
           when task_name is null then null
           else 'Seguimiento de contacto eliminado'
         end
   where user_id = v_user_id
     and contact_id = p_contact_id;
  get diagnostics v_tasks_scrubbed = row_count;

  -- This migration runs before message_templates is created. Dynamic SQL keeps
  -- the function installable now and archives contact-specific templates once
  -- that table exists, without retaining the deleted relationship.
  if pg_catalog.to_regclass('public.message_templates') is not null then
    execute
      'update public.message_templates '
      || 'set contact_id = null, archived_at = coalesce(archived_at, pg_catalog.now()) '
      || 'where user_id = $1 and contact_id = $2'
      using v_user_id, p_contact_id;
    get diagnostics v_templates_archived = row_count;
  end if;

  -- A linked account must not keep pointing at a leader after its relationship
  -- contact is removed.
  update public.settings child
     set parent_id = null
   where child.parent_id = v_user_id
     and exists (
       select 1
         from public.partners relationship
        where relationship.user_id = v_user_id
          and relationship.contact_id = p_contact_id
          and relationship.partner_user_id = child.user_id
     );

  delete from public.partners
   where user_id = v_user_id
     and contact_id = p_contact_id;
  get diagnostics v_partners_unlinked = row_count;

  delete from public.contacts
   where id = p_contact_id
     and user_id = v_user_id;

  return jsonb_build_object(
    'status', 'anonymized',
    'contact_id', p_contact_id,
    'sales_preserved', v_sales_preserved,
    'tasks_deleted', v_tasks_deleted,
    'tasks_scrubbed', v_tasks_scrubbed,
    'templates_archived', v_templates_archived,
    'partners_unlinked', v_partners_unlinked
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.archive_message_template(p_template_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_template public.message_templates%rowtype;
begin
  if v_user_id is null then
    raise exception using errcode = '42501', message = 'authentication_required';
  end if;
  if not public.has_app_entitlement(v_user_id) then
    raise exception using errcode = '42501', message = 'app_entitlement_required';
  end if;
  update public.message_templates
     set archived_at = now(), is_default = false
   where user_id = v_user_id
     and template_id = p_template_id
     and archived_at is null
  returning * into v_template;
  if not found then
    raise exception using errcode = '42501', message = 'template_not_owned_or_missing';
  end if;
  return to_jsonb(v_template);
end;
$function$

CREATE OR REPLACE FUNCTION public.archive_template_category(p_category_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_category public.template_categories%rowtype;
begin
  if v_user_id is null then
    raise exception using errcode = '42501', message = 'authentication_required';
  end if;
  if not public.has_app_entitlement(v_user_id) then
    raise exception using errcode = '42501', message = 'app_entitlement_required';
  end if;

  select * into v_category
    from public.template_categories
   where id = p_category_id
     and user_id = v_user_id
     and archived_at is null
   for update;
  if not found then
    raise exception using errcode = '42501', message = 'category_not_owned_or_missing';
  end if;

  update public.message_templates
     set category_id = null
   where user_id = v_user_id
     and category_id = p_category_id;
  update public.template_categories
     set archived_at = now()
   where id = p_category_id
     and user_id = v_user_id
  returning * into v_category;

  return to_jsonb(v_category);
end;
$function$

CREATE OR REPLACE FUNCTION public.assert_stripe_connect_checkout_ready()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if exists (
    select 1
      from public.stripe_connect_charges
     where reconciliation_status <> 'balanced'
  ) or exists (
    select 1
      from public.stripe_connect_anomalies
     where status = 'open'
  ) then
    raise exception 'stripe_connect_ledger_unhealthy';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.begin_account_deletion(p_user_id uuid, p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_request public.account_deletion_requests%rowtype;
  v_account public.billing_accounts%rowtype;
  v_execute_at timestamptz;
  v_should_schedule boolean := false;
begin
  if p_user_id is null or p_operation_id is null then
    raise exception 'invalid_deletion_request';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(p_user_id::text, 1)
  );

  select *
    into v_request
    from public.account_deletion_requests
   where user_id = p_user_id
   for update;

  if not found then
    if exists (
      select 1 from public.account_deletion_requests
       where operation_id = p_operation_id and user_id is distinct from p_user_id
    ) then
      raise exception 'operation_id_already_used';
    end if;
    insert into public.account_deletion_requests (operation_id, user_id)
    values (p_operation_id, p_user_id)
    returning * into v_request;
  elsif v_request.status = 'processing'
        and v_request.execute_at <= now()
        and v_request.locked_at > now() - interval '15 minutes' then
    return jsonb_build_object(
      'request_id', v_request.id,
      'status', v_request.status,
      'operation_id', v_request.operation_id,
      'user_id', v_request.user_id,
      'stripe_customer_id', v_request.stripe_customer_id,
      'stripe_subscription_id', v_request.stripe_subscription_id,
      'execute_at', v_request.execute_at,
      'should_schedule', false,
      'already_processing', true
    );
  end if;

  select *
    into v_account
    from public.billing_accounts
   where user_id = p_user_id and anonymized_at is null;

  if v_account.id is not null
     and v_account.entitlement_eligible
     and v_account.subscription_status = 'active'
     and v_account.access_blocked_reason is null
     and v_account.current_period_end is not null
     and v_account.current_period_end > now() then
    v_execute_at := v_account.current_period_end;
    v_should_schedule := true;
  else
    v_execute_at := now();
  end if;

  update public.account_deletion_requests
     set status = case when v_should_schedule then 'scheduling' else 'processing' end,
         execute_at = v_execute_at,
         stripe_customer_id = v_account.stripe_customer_id,
         stripe_subscription_id = v_account.stripe_subscription_id,
         attempt_count = attempt_count + 1,
         locked_at = now(),
         failure_code = null
   where id = v_request.id
   returning * into v_request;

  return jsonb_build_object(
    'request_id', v_request.id,
    'status', v_request.status,
    'operation_id', v_request.operation_id,
    'user_id', v_request.user_id,
    'stripe_customer_id', v_request.stripe_customer_id,
    'stripe_subscription_id', v_request.stripe_subscription_id,
    'execute_at', v_request.execute_at,
    'should_schedule', v_should_schedule
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.bulk_anonymize_contacts(p_operation_id uuid, p_contact_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_ids uuid[];
  v_request_hash text;
  v_previous public.contact_batch_operations%rowtype;
  v_contact_id uuid;
  v_result jsonb;
begin
  if v_user_id is null then
    raise exception using errcode = '42501', message = 'authentication_required';
  end if;
  if not public.has_app_entitlement(v_user_id) then
    raise exception using errcode = '42501', message = 'app_entitlement_required';
  end if;
  if p_operation_id is null then
    raise exception using errcode = '22023', message = 'operation_id_required';
  end if;
  select pg_catalog.array_agg(id order by id) into v_ids
    from (select distinct pg_catalog.unnest(p_contact_ids) as id) selected;
  if coalesce(pg_catalog.cardinality(v_ids), 0) < 1 or pg_catalog.cardinality(v_ids) > 1000 then
    raise exception using errcode = '22023', message = 'contact_ids_must_have_1_to_1000_items';
  end if;
  v_request_hash := encode(extensions.digest(pg_catalog.convert_to(
    jsonb_build_object('contact_ids', to_jsonb(v_ids))::text,
    'UTF8'
  ), 'sha256'), 'hex');

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('contact_batch:' || v_user_id::text || ':' || p_operation_id::text, 0)
  );
  select * into v_previous
    from public.contact_batch_operations
   where user_id = v_user_id and operation_id = p_operation_id;
  if found then
    if v_previous.operation_kind <> 'anonymize' or v_previous.request_hash <> v_request_hash then
      raise exception using errcode = '23505', message = 'operation_id_reused_with_different_contact_batch';
    end if;
    return v_previous.result;
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('contact_bulk:' || v_user_id::text, 0)
  );
  if (select count(*) from public.contacts where user_id = v_user_id and id = any(v_ids)) <> pg_catalog.cardinality(v_ids) then
    raise exception using errcode = '42501', message = 'contact_not_owned_or_missing';
  end if;
  if exists (
    select 1 from public.partners
     where user_id = v_user_id and contact_id = any(v_ids) and partner_user_id is not null
  ) then
    raise exception using errcode = '23514', message = 'linked_partner_delete_protected';
  end if;

  foreach v_contact_id in array v_ids loop
    perform public.anonymize_contact(v_contact_id);
  end loop;

  v_result := jsonb_build_object(
    'status', 'completed',
    'anonymized', pg_catalog.cardinality(v_ids)
  );
  insert into public.contact_batch_operations (
    user_id, operation_id, operation_kind, request_hash, result
  ) values (v_user_id, p_operation_id, 'anonymize', v_request_hash, v_result);
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.bulk_update_contact_type(p_operation_id uuid, p_contact_ids uuid[], p_contact_type text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_ids uuid[];
  v_request_hash text;
  v_previous public.contact_batch_operations%rowtype;
  v_contact public.contacts%rowtype;
  v_days integer;
  v_changed integer := 0;
  v_result jsonb;
begin
  if v_user_id is null then
    raise exception using errcode = '42501', message = 'authentication_required';
  end if;
  if not public.has_app_entitlement(v_user_id) then
    raise exception using errcode = '42501', message = 'app_entitlement_required';
  end if;
  if p_operation_id is null then
    raise exception using errcode = '22023', message = 'operation_id_required';
  end if;
  if p_contact_type is not null and p_contact_type not in (
    'prospecto_producto', 'prospecto_partner', 'cliente_producto', 'partner'
  ) then
    raise exception using errcode = '22023', message = 'invalid_contact_type';
  end if;

  select pg_catalog.array_agg(id order by id) into v_ids
    from (select distinct pg_catalog.unnest(p_contact_ids) as id) selected;
  if coalesce(pg_catalog.cardinality(v_ids), 0) < 1 or pg_catalog.cardinality(v_ids) > 1000 then
    raise exception using errcode = '22023', message = 'contact_ids_must_have_1_to_1000_items';
  end if;
  v_request_hash := encode(extensions.digest(pg_catalog.convert_to(
    jsonb_build_object('contact_ids', to_jsonb(v_ids), 'contact_type', p_contact_type)::text,
    'UTF8'
  ), 'sha256'), 'hex');

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('contact_batch:' || v_user_id::text || ':' || p_operation_id::text, 0)
  );
  select * into v_previous
    from public.contact_batch_operations
   where user_id = v_user_id and operation_id = p_operation_id;
  if found then
    if v_previous.operation_kind <> 'change_type' or v_previous.request_hash <> v_request_hash then
      raise exception using errcode = '23505', message = 'operation_id_reused_with_different_contact_batch';
    end if;
    return v_previous.result;
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('contact_bulk:' || v_user_id::text, 0)
  );
  if (select count(*) from public.contacts where user_id = v_user_id and id = any(v_ids)) <> pg_catalog.cardinality(v_ids) then
    raise exception using errcode = '42501', message = 'contact_not_owned_or_missing';
  end if;
  if p_contact_type is distinct from 'partner' and exists (
    select 1 from public.partners
     where user_id = v_user_id and contact_id = any(v_ids) and partner_user_id is not null
  ) then
    raise exception using errcode = '23514', message = 'linked_partner_type_protected';
  end if;

  for v_contact in
    select * from public.contacts
     where user_id = v_user_id and id = any(v_ids)
     order by id for update
  loop
    if v_contact.contact_type is not distinct from p_contact_type then
      continue;
    end if;

    if v_contact.contact_type in ('prospecto_produto', 'prospecto_producto') then
      delete from public.tasks
       where user_id = v_user_id and contact_id = v_contact.id
         and origin = 'contact_automation'
         and task_area = 'prospecto_producto' and not coalesce(completed, false);
    end if;
    if v_contact.contact_type = 'prospecto_partner' then
      delete from public.tasks
       where user_id = v_user_id and contact_id = v_contact.id
         and origin = 'contact_automation'
         and task_area = 'prospecto_partner' and not coalesce(completed, false);
    end if;
    if v_contact.contact_type = 'partner' and p_contact_type is distinct from 'partner' then
      delete from public.tasks
       where user_id = v_user_id and contact_id = v_contact.id
         and origin = 'partner_automation'
         and task_area = 'partner' and not coalesce(completed, false);
      delete from public.partners
       where user_id = v_user_id and contact_id = v_contact.id and partner_user_id is null;
    end if;
    if p_contact_type not in ('cliente_producto', 'partner') or p_contact_type is null then
      delete from public.tasks
       where user_id = v_user_id and contact_id = v_contact.id
         and origin = 'contact_automation'
         and task_area = 'referidos' and not coalesce(completed, false);
    end if;

    update public.contacts set contact_type = p_contact_type
     where id = v_contact.id and user_id = v_user_id;

    if p_contact_type in ('prospecto_producto', 'prospecto_partner') then
      for v_days in select value from unnest(array[0, 3, 7, 12, 18, 25]) as value loop
        insert into public.tasks (
          user_id, contact_id, category, subcategory, template_subcategory,
          task_name, task_area, due_date, completed, origin
        ) values (
          v_user_id,
          v_contact.id,
          'seguimiento',
          p_contact_type || '_msg_' || (array_position(array[0, 3, 7, 12, 18, 25], v_days))::text,
          p_contact_type || '_msg_' || (array_position(array[0, 3, 7, 12, 18, 25], v_days))::text,
          case p_contact_type
            when 'prospecto_producto' then 'Prospecto Producto – Seguimiento ' || (array_position(array[0, 3, 7, 12, 18, 25], v_days))::text
            else 'Prospecto Partner – Seguimiento ' || (array_position(array[0, 3, 7, 12, 18, 25], v_days))::text
          end,
          p_contact_type,
          current_date + v_days,
          false,
          'contact_automation'
        );
      end loop;
    end if;

    if p_contact_type = 'partner' then
      if not exists (
        select 1 from public.partners where user_id = v_user_id and contact_id = v_contact.id
      ) then
        insert into public.partners (
          user_id, contact_id, start_date, fast_start_deadline, fast_start_status,
          fase_actual, qteam_completed, fs_level1_completed, fs_level2_completed,
          xteam_completed
        ) values (
          v_user_id, v_contact.id, current_date, current_date + 120, 'activo',
          1, false, false, false, false
        );
      end if;
      if not exists (
        select 1 from public.tasks where user_id = v_user_id and contact_id = v_contact.id
          and origin = 'partner_automation'
          and task_area = 'partner' and not coalesce(completed, false)
      ) then
        insert into public.tasks (
          user_id, contact_id, category, subcategory, template_subcategory,
          task_name, task_area, due_date, completed, origin
        ) values (
          v_user_id, v_contact.id, 'seguimiento', 'partner_invitar_zynergia',
          'partner_invitar_zynergia', 'Invitar a Zynergia para ver su avance real',
          'partner', current_date, false, 'partner_automation'
        );
      end if;
    end if;

    if p_contact_type in ('cliente_producto', 'partner') and not exists (
      select 1 from public.tasks where user_id = v_user_id and contact_id = v_contact.id
        and origin = 'contact_automation'
        and task_area = 'referidos' and not coalesce(completed, false)
    ) then
      insert into public.tasks (
        user_id, contact_id, category, subcategory, template_subcategory,
        task_name, task_area, due_date, completed, origin
      ) values (
        v_user_id, v_contact.id, 'seguimiento', 'referido', 'referido',
        'Pedir referido', 'referidos',
        greatest(current_date, coalesce(v_contact.created_at::date, current_date) + 30), false,
        'contact_automation'
      );
    end if;

    v_changed := v_changed + 1;
  end loop;

  v_result := jsonb_build_object('status', 'completed', 'changed', v_changed);
  insert into public.contact_batch_operations (
    user_id, operation_id, operation_kind, request_hash, result
  ) values (v_user_id, p_operation_id, 'change_type', v_request_hash, v_result);
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_billing_account(p_user_id uuid, p_email text, p_expected_stripe_customer_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_email text := nullif(lower(btrim(p_email)), '');
  v_account public.billing_accounts%rowtype;
begin
  if v_email is null then
    raise exception 'verified_email_required';
  end if;
  if p_user_id is null or not exists (
    select 1
      from auth.users
     where id = p_user_id
       and lower(email) = v_email
       and email_confirmed_at is not null
  ) then
    raise exception 'invalid_user';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_email, 0));

  select *
    into v_account
    from public.billing_accounts
   where user_id = p_user_id
     and anonymized_at is null
   for update;

  if found then
    if not v_account.entitlement_eligible
       and v_account.subscription_status in ('active', 'trialing', 'past_due', 'unpaid', 'paused', 'incomplete') then
      return jsonb_build_object('status', 'conflict', 'reason', 'unsupported_price');
    end if;
    return jsonb_build_object(
      'status', 'existing',
      'stripe_customer_id', v_account.stripe_customer_id,
      'stripe_subscription_id', v_account.stripe_subscription_id
    );
  end if;

  if p_expected_stripe_customer_id is null then
    return jsonb_build_object('status', 'validation_required');
  end if;
  if p_expected_stripe_customer_id !~ '^cus_' then
    raise exception 'invalid_expected_stripe_customer_id';
  end if;

  select *
    into v_account
    from public.billing_accounts
   where stripe_customer_id = p_expected_stripe_customer_id
   for update;

  if not found or v_account.anonymized_at is not null then
    return jsonb_build_object('status', 'not_found');
  end if;
  if v_account.user_id is not null then
    return jsonb_build_object('status', 'conflict', 'reason', 'billing_account_already_owned');
  end if;
  if v_account.claim_email is distinct from v_email then
    return jsonb_build_object('status', 'conflict', 'reason', 'validated_customer_email_mismatch');
  end if;
  if not v_account.entitlement_eligible
     and v_account.subscription_status in ('active', 'trialing', 'past_due', 'unpaid', 'paused', 'incomplete') then
    return jsonb_build_object('status', 'conflict', 'reason', 'unsupported_price');
  end if;

  update public.billing_accounts
     set user_id = p_user_id,
         claim_email = null
   where id = v_account.id
     and user_id is null
   returning * into v_account;

  if not found then
    return jsonb_build_object('status', 'conflict', 'reason', 'billing_claim_race');
  end if;

  perform public.refresh_stripe_access_grant(v_account.stripe_customer_id);

  return jsonb_build_object(
    'status', 'claimed',
    'stripe_customer_id', v_account.stripe_customer_id,
    'stripe_subscription_id', v_account.stripe_subscription_id
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_stripe_webhook_event(p_event_id text, p_event_type text, p_event_created_at timestamp with time zone, p_payload_sha256 text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_rows integer;
  v_existing_hash text;
begin
  if p_event_id is null or p_payload_sha256 !~ '^[0-9a-f]{64}$' then
    raise exception 'invalid_webhook_event';
  end if;

  insert into public.stripe_webhook_events (
    event_id, event_type, event_created_at, payload_sha256
  ) values (
    p_event_id, p_event_type, p_event_created_at, p_payload_sha256
  )
  on conflict (event_id) do nothing;
  get diagnostics v_rows = row_count;
  if v_rows = 1 then
    return true;
  end if;

  select payload_sha256
    into v_existing_hash
    from public.stripe_webhook_events
   where event_id = p_event_id;
  if v_existing_hash is distinct from p_payload_sha256 then
    raise exception 'webhook_event_hash_mismatch';
  end if;

  update public.stripe_webhook_events
     set status = 'processing',
         attempt_count = attempt_count + 1,
         locked_at = now(),
         processed_at = null,
         last_error = null
   where event_id = p_event_id
     and (
       status = 'failed'
       or (status = 'processing' and locked_at < now() - interval '5 minutes')
     );
  get diagnostics v_rows = row_count;
  return v_rows = 1;
end;
$function$

CREATE OR REPLACE FUNCTION public.complete_onboarding()
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_completed_at timestamptz := now();
  v_rows integer;
begin
  if v_user_id is null then
    raise exception 'authentication_required';
  end if;
  if not public.has_app_entitlement(v_user_id) then
    raise exception 'app_entitlement_required';
  end if;

  update public.settings
     set onboarding_completed_at = coalesce(onboarding_completed_at, v_completed_at)
   where user_id = v_user_id;
  get diagnostics v_rows = row_count;
  if v_rows <> 1 then
    raise exception 'settings_row_missing';
  end if;

  select onboarding_completed_at
    into v_completed_at
    from public.settings
   where user_id = v_user_id;
  return v_completed_at;
end;
$function$

CREATE OR REPLACE FUNCTION public.complete_stripe_connect_reconciliation(p_stripe_charge_id text, p_net_clawback_amount bigint, p_event_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_charge public.stripe_connect_charges%rowtype;
  v_state jsonb;
begin
  select * into v_charge
    from public.stripe_connect_charges
   where stripe_charge_id = p_stripe_charge_id
   for update;
  if not found then raise exception 'connect_charge_missing'; end if;
  v_state := public.get_stripe_connect_charge_state(p_stripe_charge_id);
  if (v_state->>'net_clawback_amount')::bigint <> p_net_clawback_amount
     or p_net_clawback_amount <> v_charge.desired_clawback_amount then
    raise exception 'connect_reconciliation_not_balanced';
  end if;
  update public.stripe_connect_charges
     set reconciled_net_clawback_amount = p_net_clawback_amount,
