end;
$function$

CREATE OR REPLACE FUNCTION public.create_template_share_bundle(p_operation_id uuid, p_template_ids text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_template_ids text[];
  v_request_hash text;
  v_snapshot jsonb;
  v_token text;
  v_bundle public.template_share_bundles%rowtype;
begin
  if v_user_id is null then
    raise exception using errcode = '42501', message = 'authentication_required';
  end if;
  if not public.has_app_entitlement(v_user_id) then
    raise exception using errcode = '42501', message = 'app_entitlement_required';
  end if;
  if p_operation_id is null then
    raise exception using errcode = '22023', message = 'operation_id_required';
  end if;
  if coalesce(cardinality(p_template_ids), 0) not between 1 and 120
     or exists (
       select 1
         from unnest(coalesce(p_template_ids, array[]::text[])) as item(template_id)
        where char_length(btrim(coalesce(item.template_id, ''))) not between 1 and 200
     ) then
    raise exception using errcode = '22023', message = 'template_ids_must_be_1_to_120_unique_values';
  end if;
  select array_agg(template_id order by template_id)
    into v_template_ids
    from (
      select distinct btrim(item.template_id) as template_id
        from unnest(coalesce(p_template_ids, array[]::text[])) as item(template_id)
       where nullif(btrim(item.template_id), '') is not null
    ) selected;
  if cardinality(v_template_ids) <> cardinality(p_template_ids) then
    raise exception using errcode = '22023', message = 'template_ids_must_be_1_to_120_unique_values';
  end if;

  v_request_hash := encode(
    extensions.digest(
      convert_to(array_to_string(v_template_ids, chr(31)), 'UTF8'),
      'sha256'
    ),
    'hex'
  );
  v_token := encode(
    extensions.digest(
      convert_to('template-share:' || v_user_id::text || ':' || p_operation_id::text, 'UTF8'),
      'sha256'
    ),
    'hex'
  );

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('template_share:' || v_user_id::text || ':' || p_operation_id::text, 0)
  );
  select * into v_bundle
    from public.template_share_bundles
   where owner_id = v_user_id and operation_id = p_operation_id;
  if found then
    if v_bundle.request_hash <> v_request_hash then
      raise exception using errcode = '23505', message = 'operation_id_reused_with_different_templates';
    end if;
    return jsonb_build_object(
      'id', v_bundle.id,
      'token', v_token,
      'expires_at', v_bundle.expires_at,
      'created_at', v_bundle.created_at,
      'created', false
    );
  end if;

  select jsonb_agg(
    jsonb_build_object(
      'name', btrim(template.name),
      'content', template.content,
      'situation', template.situation,
      'tone', template.tone,
      'category_name', category.name
    ) order by selected.ordinality
  ) into v_snapshot
    from unnest(v_template_ids) with ordinality selected(template_id, ordinality)
    join public.message_templates template
      on template.template_id = selected.template_id
     and template.user_id = v_user_id
     and template.archived_at is null
    left join public.template_categories category
      on category.id = template.category_id
     and category.user_id = v_user_id
     and category.situation = template.situation
     and category.archived_at is null
   where char_length(btrim(coalesce(template.name, ''))) between 1 and 100
     and char_length(coalesce(template.content, '')) between 1 and 5000
     and template.situation in (
       'repurchase', 'product', 'product-prospect', 'business',
       'fast-start', 'referral', 'manual'
     )
     and coalesce(template.tone, '') ~ '^[a-z0-9_-]{1,30}$'
     and regexp_replace(
       template.content,
       '\{\{(contact\.full_name|product\.name|product\.link_url)\}\}',
       '',
       'g'
     ) !~ '\{\{[^{}]+\}\}';

  if coalesce(jsonb_array_length(v_snapshot), 0) <> cardinality(v_template_ids) then
    raise exception using errcode = '42501', message = 'template_not_owned_missing_or_invalid';
  end if;

  insert into public.template_share_bundles (
    owner_id, operation_id, request_hash, token_hash, snapshot
  )
  values (
    v_user_id,
    p_operation_id,
    v_request_hash,
    encode(extensions.digest(v_token, 'sha256'), 'hex'),
    v_snapshot
  )
  returning * into v_bundle;

  return jsonb_build_object(
    'id', v_bundle.id,
    'token', v_token,
    'expires_at', v_bundle.expires_at,
    'created_at', v_bundle.created_at,
    'created', true
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.delete_user_data(p_request_id uuid, p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_request public.account_deletion_requests%rowtype;
  v_table text;
begin
  select *
    into v_request
    from public.account_deletion_requests
   where id = p_request_id
   for update;

  if not found or v_request.user_id is distinct from p_user_id then
    raise exception 'invalid_deletion_request';
  end if;
  if v_request.status = 'completed' then
    return;
  end if;

  if pg_catalog.to_regclass('public.partners') is not null then
    update public.partners set partner_user_id = null where partner_user_id = p_user_id;
  end if;
  if pg_catalog.to_regclass('public.settings') is not null then
    update public.settings set parent_id = null where parent_id = p_user_id;
  end if;

  foreach v_table in array array[
    'tasks', 'sales', 'partners', 'contacts', 'tags', 'product_links',
    'user_templates', 'user_products', 'message_templates', 'notifications',
    'template_share_imports', 'template_categories', 'sale_orders',
    'contact_batch_operations', 'settings'
  ] loop
    if pg_catalog.to_regclass('public.' || v_table) is not null
       and exists (
         select 1 from information_schema.columns
          where table_schema = 'public' and table_name = v_table and column_name = 'user_id'
       ) then
      execute pg_catalog.format('delete from public.%I where user_id = $1', v_table)
        using p_user_id;
    end if;
  end loop;

  if pg_catalog.to_regclass('public.template_share_bundles') is not null then
    delete from public.template_share_bundles where owner_id = p_user_id;
  end if;

  delete from public.access_grants where user_id = p_user_id;
  update public.billing_accounts
     set user_id = null,
         claim_email = null,
         operation_id = null,
         operation_expires_at = null,
         anonymized_at = coalesce(anonymized_at, now())
   where user_id = p_user_id;

  update public.account_deletion_requests
     set status = 'data_deleted', failure_code = null
   where id = p_request_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.ensure_partner_code()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_code text;
  v_attempt integer;
begin
  if auth.uid() is null then
    raise exception 'authentication_required';
  end if;
  if not public.has_app_entitlement(auth.uid()) then
    raise exception 'app_entitlement_required';
  end if;

  select partner_code
    into v_code
    from public.settings
   where user_id = auth.uid()
   for update;
  if not found then
    raise exception 'settings_row_missing';
  end if;
  if v_code is not null then
    return v_code;
  end if;

  for v_attempt in 1..8 loop
    v_code := upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8));
    begin
      update public.settings
         set partner_code = v_code
       where user_id = auth.uid()
         and partner_code is null;
      return v_code;
    exception when unique_violation then
      -- A collision is harmless; generate another opaque code.
    end;
  end loop;

  raise exception 'partner_code_generation_failed';
end;
$function$

