CREATE OR REPLACE FUNCTION public.get_stripe_connect_charge_state(p_stripe_charge_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_charge public.stripe_connect_charges%rowtype;
  v_transfers jsonb;
  v_forward bigint;
  v_reversed bigint;
  v_net bigint;
begin
  select * into v_charge
    from public.stripe_connect_charges
   where stripe_charge_id = p_stripe_charge_id;
  if not found then
    return null;
  end if;

  select coalesce(jsonb_agg(to_jsonb(t) order by
           case when t.kind = 'restoration' then 0 else 1 end,
           t.stripe_created_at desc, t.stripe_transfer_id), '[]'::jsonb),
         coalesce(sum(t.amount), 0),
         coalesce(sum(t.amount_reversed), 0)
    into v_transfers, v_forward, v_reversed
    from public.stripe_connect_transfers t
   where t.stripe_charge_id = p_stripe_charge_id;

  v_net := v_charge.original_transfer_amount - (v_forward - v_reversed);
  return jsonb_build_object(
    'charge', to_jsonb(v_charge),
    'transfers', v_transfers,
    'forward_amount', v_forward,
    'reversed_amount', v_reversed,
    'net_clawback_amount', v_net
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.import_contacts(p_operation_id uuid, p_contacts jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_previous public.contact_batch_operations%rowtype;
  v_request_hash text;
  v_item jsonb;
  v_name text;
  v_phone text;
  v_country_code text;
  v_country_iso text;
  v_phone_raw text;
  v_created integer := 0;
  v_duplicates integer := 0;
  v_result jsonb;
begin
  if v_user_id is null then
    raise exception using errcode = '42501', message = 'authentication_required';
  end if;
  if not public.has_app_entitlement(v_user_id) then
    raise exception using errcode = '42501', message = 'app_entitlement_required';
  end if;
  if p_operation_id is null then
    raise exception using errcode = '22023', message = 'operation_id_required';
  end if;
  if p_contacts is null or pg_catalog.jsonb_typeof(p_contacts) <> 'array'
     or pg_catalog.jsonb_array_length(p_contacts) < 1
     or pg_catalog.jsonb_array_length(p_contacts) > 1000 then
    raise exception using errcode = '22023', message = 'contacts_batch_must_have_1_to_1000_items';
  end if;
  v_request_hash := encode(
    extensions.digest(pg_catalog.convert_to(p_contacts::text, 'UTF8'), 'sha256'),
    'hex'
  );

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('contact_batch:' || v_user_id::text || ':' || p_operation_id::text, 0)
  );
  select * into v_previous
    from public.contact_batch_operations
   where user_id = v_user_id and operation_id = p_operation_id;
  if found then
    if v_previous.operation_kind <> 'import' or v_previous.request_hash <> v_request_hash then
      raise exception using errcode = '23505', message = 'operation_id_reused_with_different_contact_batch';
    end if;
    return v_previous.result;
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('contact_import:' || v_user_id::text, 0)
  );

  for v_item in select value from pg_catalog.jsonb_array_elements(p_contacts) loop
    v_name := btrim(coalesce(v_item ->> 'full_name', ''));
    v_phone := btrim(coalesce(v_item ->> 'phone_e164', v_item ->> 'phone', ''));
    v_country_code := btrim(coalesce(v_item ->> 'country_code', ''));
    v_country_iso := nullif(upper(btrim(coalesce(v_item ->> 'phone_country_iso', ''))), '');
    v_phone_raw := left(coalesce(v_item ->> 'phone_raw', v_phone), 80);

    if length(v_name) < 1 or length(v_name) > 120 then
      raise exception using errcode = '22023', message = 'invalid_import_contact_name';
    end if;
    if v_phone !~ '^\+[1-9][0-9]{7,14}$' then
      raise exception using errcode = '22023', message = 'invalid_import_contact_phone';
    end if;
    if v_country_code !~ '^\+[1-9][0-9]{0,3}$' then
      raise exception using errcode = '22023', message = 'invalid_import_country_code';
    end if;
    if v_country_iso is not null and v_country_iso !~ '^[A-Z]{2}$' then
      raise exception using errcode = '22023', message = 'invalid_import_country_iso';
    end if;

    if exists (
      select 1
        from public.contacts contact
       where contact.user_id = v_user_id
         and (
           contact.phone_e164 = v_phone
           or (
             contact.phone_e164 is null
             and btrim(coalesce(contact.phone, '')) ~ '^\+'
             and '+' || pg_catalog.regexp_replace(contact.phone, '[^0-9]', '', 'g') = v_phone
           )
         )
    ) then
      v_duplicates := v_duplicates + 1;
      continue;
    end if;

    insert into public.contacts (
      user_id, full_name, phone, country_code, contact_type, notes, tag_ids,
      phone_e164, phone_country_iso, phone_raw, import_source
    ) values (
      v_user_id, v_name, v_phone, v_country_code, null, null, '[]'::jsonb,
      v_phone, v_country_iso, v_phone_raw, 'device'
    );
    v_created := v_created + 1;
  end loop;

  v_result := jsonb_build_object(
    'status', 'completed',
    'created', v_created,
    'duplicates', v_duplicates
  );
  insert into public.contact_batch_operations (
    user_id, operation_id, operation_kind, request_hash, result
  ) values (v_user_id, p_operation_id, 'import', v_request_hash, v_result);
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.import_partner_clients(p_partner_user_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  imported INTEGER := 0;
  r RECORD;
  caller_id UUID := auth.uid();
BEGIN
  FOR r IN 
    SELECT * FROM contacts 
    WHERE user_id = p_partner_user_id AND contact_type = 'cliente_producto'
  LOOP
    INSERT INTO contacts (user_id, full_name, phone, country_code, notes, contact_type, tag_ids)
    VALUES (caller_id, r.full_name, r.phone, r.country_code, r.notes, 'cliente_producto', r.tag_ids);
    imported := imported + 1;
  END LOOP;
  RETURN imported;
END;
$function$

CREATE OR REPLACE FUNCTION public.import_template_share_bundle(p_operation_id uuid, p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_bundle public.template_share_bundles%rowtype;
  v_previous public.template_share_imports%rowtype;
  v_operation_previous public.template_share_imports%rowtype;
  v_request_hash text;
  v_item jsonb;
  v_category_id uuid;
  v_template_id text;
  v_template_name text;
  v_template_ids text[] := '{}';
  v_count integer := 0;
begin
