  end if;
  if p_operation_id is null then
    raise exception using errcode = '22023', message = 'operation_id_required';
  end if;
  if p_token is null or p_token !~ '^[a-f0-9]{64}$' then
    raise exception using errcode = '22023', message = 'invalid_share_token';
  end if;
  v_request_hash := encode(extensions.digest(p_token, 'sha256'), 'hex');

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('template_import_operation:' || v_user_id::text || ':' || p_operation_id::text, 0)
  );
  select * into v_operation_previous
    from public.template_share_imports
   where user_id = v_user_id and operation_id = p_operation_id;
  if found then
    if v_operation_previous.request_hash <> v_request_hash then
      raise exception using errcode = '23505', message = 'operation_id_reused_with_different_share';
    end if;
    return jsonb_build_object(
      'bundle_id', v_operation_previous.bundle_id,
      'imported_count', v_operation_previous.imported_count,
      'template_ids', to_jsonb(v_operation_previous.imported_template_ids),
      'created', false
    );
  end if;

  select * into v_bundle
    from public.template_share_bundles
   where token_hash = v_request_hash
   for update;
  if not found then
    raise exception using errcode = '22023', message = 'share_bundle_unavailable';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('template_import_user:' || v_user_id::text, 0)
  );
  select * into v_previous
    from public.template_share_imports
   where bundle_id = v_bundle.id and user_id = v_user_id;
  if found then
    return jsonb_build_object(
      'bundle_id', v_bundle.id,
      'imported_count', v_previous.imported_count,
      'template_ids', to_jsonb(v_previous.imported_template_ids),
      'created', false
    );
  end if;
  if v_bundle.revoked_at is not null or v_bundle.expires_at <= now() then
    raise exception using errcode = '22023', message = 'share_bundle_unavailable';
  end if;

  insert into public.template_share_imports (
    bundle_id, user_id, operation_id, request_hash
  ) values (
    v_bundle.id, v_user_id, p_operation_id, v_request_hash
  );

  for v_item in select value from jsonb_array_elements(v_bundle.snapshot) loop
    v_category_id := null;
    if nullif(btrim(v_item->>'category_name'), '') is not null then
      select id into v_category_id
        from public.template_categories
       where user_id = v_user_id
         and lower(btrim(name)) = lower(btrim(v_item->>'category_name'))
         and situation = v_item->>'situation'
         and archived_at is null
       limit 1;
      if not found then
        insert into public.template_categories (user_id, name, situation)
        values (v_user_id, btrim(v_item->>'category_name'), v_item->>'situation')
        returning id into v_category_id;
      end if;
    end if;

    v_template_id := 'tpl_shared_' || replace(gen_random_uuid()::text, '-', '');
    v_template_name := v_item->>'name';
    if exists (
      select 1
        from public.message_templates template
       where template.user_id = v_user_id
         and template.archived_at is null
         and lower(btrim(template.name)) = lower(btrim(v_template_name))
    ) then
      v_template_name := left(btrim(v_template_name), 88) || ' (importada)';
    end if;
    insert into public.message_templates (
      user_id, template_id, name, content, situation, category, subcategory,
      tone, category_id, contact_id, origin, is_default
    ) values (
      v_user_id,
      v_template_id,
      v_template_name,
      v_item->>'content',
      v_item->>'situation',
      case when v_item->>'situation' = 'repurchase' then 'recompra' else 'seguimiento' end,
      v_item->>'situation',
      v_item->>'tone',
      v_category_id,
      null,
      'user',
      false
    );
    v_template_ids := array_append(v_template_ids, v_template_id);
    v_count := v_count + 1;
  end loop;

  update public.template_share_imports
     set imported_template_ids = v_template_ids,
         imported_count = v_count
   where bundle_id = v_bundle.id and user_id = v_user_id;

  return jsonb_build_object(
    'bundle_id', v_bundle.id,
    'imported_count', v_count,
    'template_ids', to_jsonb(v_template_ids),
    'created', true
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.join_upline_by_code(p_code text)
 RETURNS TABLE(upline_user_id uuid, upline_name text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_child public.settings%rowtype;
  v_upline public.settings%rowtype;
  v_existing_owner uuid;
  v_existing_partner_id uuid;
  v_contact_id uuid;
begin
  if auth.uid() is null then
    raise exception 'authentication_required';
  end if;
  if not public.has_app_entitlement(auth.uid()) then
    raise exception 'app_entitlement_required';
  end if;
  if nullif(btrim(p_code), '') is null or btrim(p_code) !~ '^[A-Za-z0-9]{4,8}$' then
    raise exception 'invalid_partner_code';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('zynergia_partner_graph', 0)
  );

  select * into v_child
    from public.settings
   where user_id = auth.uid()
   for update;
  if not found then
    raise exception 'settings_row_missing';
  end if;

  select * into v_upline
    from public.settings
   where upper(partner_code) = upper(btrim(p_code))
   for update;
  if not found then
    raise exception 'partner_code_not_found';
  end if;
  if v_upline.user_id = auth.uid() then
    raise exception 'self_link_not_allowed';
  end if;
  if v_child.parent_id is not null and v_child.parent_id <> v_upline.user_id then
    raise exception 'partner_already_linked';
  end if;

  select p.user_id, p.id
    into v_existing_owner, v_existing_partner_id
    from public.partners p
   where p.partner_user_id = auth.uid()
   for update;
  if found and v_existing_owner <> v_upline.user_id then
    raise exception 'partner_already_linked';
  end if;

  if exists (
    with recursive ancestors(user_id, parent_id) as (
      select s.user_id, s.parent_id
        from public.settings s
       where s.user_id = v_upline.user_id
      union
      select parent.user_id, parent.parent_id
        from public.settings parent
        join ancestors child on parent.user_id = child.parent_id
       where child.parent_id is not null
    )
    select 1 from ancestors where user_id = auth.uid()
  ) then
    raise exception 'partner_cycle_detected';
  end if;

  if v_existing_partner_id is null then
    insert into public.contacts (
      user_id, full_name, contact_type, phone, country_code, notes
    ) values (
      v_upline.user_id,
      coalesce(nullif(btrim(v_child.user_name), ''), 'Partner'),
      'partner', '', '+52', 'Agregado por código de invitación'
    ) returning id into v_contact_id;

    insert into public.partners (
      user_id, contact_id, partner_user_id, start_date, fast_start_deadline,
      fast_start_status, fase_actual, qteam_completed, fs_level1_completed,
      fs_level2_completed, xteam_completed
    ) values (
      v_upline.user_id, v_contact_id, auth.uid(), current_date, current_date + 120,
      'activo', 1, false, false, false, false
    );
  end if;

  update public.settings
     set parent_id = v_upline.user_id
   where user_id = auth.uid()
     and (parent_id is null or parent_id = v_upline.user_id);
  if not found then
    raise exception 'partner_already_linked';
  end if;

  return query
  select v_upline.user_id,
         coalesce(nullif(btrim(v_upline.user_name), ''), 'Líder');
end;
$function$

CREATE OR REPLACE FUNCTION public.link_existing_partner_by_code(p_partner_id uuid, p_code text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_target public.settings%rowtype;
  v_current_partner_user_id uuid;
begin
  if auth.uid() is null then
    raise exception 'authentication_required';
  end if;
  if not public.has_app_entitlement(auth.uid()) then
    raise exception 'app_entitlement_required';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('zynergia_partner_graph', 0)
  );

  select p.partner_user_id
    into v_current_partner_user_id
    from public.partners p
   where p.id = p_partner_id and p.user_id = auth.uid()
   for update;
  if not found then
    raise exception 'partner_not_found';
  end if;

  select * into v_target
    from public.settings
   where upper(partner_code) = upper(btrim(p_code))
   for update;
  if not found then
    raise exception 'partner_code_not_found';
  end if;
  if v_target.user_id = auth.uid() then
    raise exception 'self_link_not_allowed';
  end if;
  if v_current_partner_user_id is not null and v_current_partner_user_id <> v_target.user_id then
    raise exception 'partner_record_already_linked';
  end if;
  if v_target.parent_id is not null and v_target.parent_id <> auth.uid() then
    raise exception 'partner_already_linked';
  end if;
  if exists (
    with recursive ancestors(user_id, parent_id) as (
      select s.user_id, s.parent_id from public.settings s where s.user_id = auth.uid()
      union
      select parent.user_id, parent.parent_id
        from public.settings parent
        join ancestors child on parent.user_id = child.parent_id
       where child.parent_id is not null
    )
    select 1 from ancestors where user_id = v_target.user_id
  ) then
    raise exception 'partner_cycle_detected';
  end if;
  if exists (
    select 1 from public.partners p
     where p.partner_user_id = v_target.user_id
       and p.id <> p_partner_id
  ) then
    raise exception 'partner_duplicate_link';
  end if;

  update public.partners
     set partner_user_id = v_target.user_id
   where id = p_partner_id and user_id = auth.uid();
  update public.settings
     set parent_id = auth.uid()
   where user_id = v_target.user_id
     and (parent_id is null or parent_id = auth.uid());
  return v_target.user_id;
end;
$function$

